def test_top_customers_ranks_by_lifetime_value_then_customer_id(shop):
    shop.customers.handle_register({"customer_id": "c3", "name": "Linus", "email": "linus@example.com"})
    shop.customers.handle_register({"customer_id": "c4", "name": "Idle", "email": "idle@example.com"})
    shop.customers.handle_register({"customer_id": "c5", "name": "Cancels", "email": "cancels@example.com"})
